import {roles,labels,actions,initialState,transition,resetCase,restoreState} from './prototype-engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='extorsion-peru-prototype-v1';let storage=true,state=initialState(),caseId='DEMO-001',role='pnp',pending=null;
try{const stored=localStorage.getItem(key);if(stored)state=restoreState(stored)||initialState();}catch{storage=false;}
const help={pnp:'Preserva, corrobora, solicita medidas y pide correcciones.',fiscal:'Revisa el expediente y registra coordinación fiscal.',uif:'Decide la solicitud financiera y gestiona incidencias.',juez:'Convalida o revoca la medida financiera del ejemplo.',banco:'Recibe órdenes, ejecuta o informa incidencias; libera cuando procede.',osiptel:'Valida y transmite requerimientos de baja o reactivación.',telco:'Ejecuta la orden recibida y registra incidencias o reactivación.',auditor:'Consulta estados y traza del ejercicio; no autoriza ni ejecuta.'};
$('#proto-role').innerHTML=Object.entries(roles).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');
const l=x=>esc(labels[x]||x), money=x=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:0}).format(x);
const roleName=id=>roles[id]||id;
function save(){try{localStorage.setItem(key,JSON.stringify(state));storage=true;}catch{storage=false;}}
function buttons(ids,c){return '<div class="proto-actions">'+ids.map(id=>{const a=actions[id],enabled=a.role===role&&a.can(c);return '<button type="button" data-action="'+id+'" '+(!enabled?'disabled':'')+' title="'+esc(enabled?'Abrir decisión':a.role!==role?'Corresponde a '+roles[a.role]:'Requiere una etapa previa o ya fue resuelta')+'">'+esc(a.label)+'<small>'+esc(roles[a.role])+'</small></button>';}).join('')+'</div>';}
function card(title,status,content,ids,c,extra=''){return '<section class="proto-card '+extra+'"><p class="proto-chip">'+l(status)+'</p><h3>'+title+'</h3>'+content+buttons(ids,c)+'</section>';}
function snapshot(c){return 'Expediente: '+labels[c.file]+' · Banco: '+labels[c.bank]+' · Telco: '+labels[c.telco]+' · Control judicial: '+labels[c.review];}
function timeline(){const filter=$('#proto-filter').value,events=state.events.filter(ev=>ev.caseId===caseId&&(filter==='all'||ev.outcome===filter));
 $('#proto-timeline').innerHTML=events.length?events.slice().reverse().map(ev=>'<li class="'+(ev.outcome==='denegado'?'blocked':'done')+'"><div class="proto-top"><strong>#'+ev.sequence+' · '+esc(ev.action)+'</strong><span class="proto-chip">'+esc(ev.outcome)+'</span></div><p><b>'+esc(ev.actor)+'</b> · <time datetime="'+esc(ev.at)+'">'+esc(new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',dateStyle:'short',timeStyle:'medium'}).format(new Date(ev.at)))+' · Lima</time></p><p>'+esc(ev.reason)+'</p><details><summary>Ver cambio y constancia</summary><p class="proto-muted"><b>Antes:</b> '+esc(snapshot(ev.before))+'</p><p class="proto-muted"><b>Después:</b> '+esc(snapshot(ev.after))+'</p><p class="proto-muted">'+esc(ev.signature)+'</p></details></li>').join(''):'<li>No hay eventos para este filtro. Comienza preservando la evidencia desde la vista Policía.</li>';
}
function render(message){const c=state.cases.find(x=>x.id===caseId);$('#proto-role').value=role;$('#proto-role-help').textContent=help[role];
 $('#proto-cases').innerHTML=state.cases.map(x=>'<button type="button" data-case="'+x.id+'" aria-pressed="'+(x.id===caseId)+'"><strong>'+x.id+'</strong><span>'+esc(x.title)+'</span><small>'+l(x.file)+'</small></button>').join('');
 $('#proto-id').textContent=c.id+' · expediente ficticio';$('#proto-title').textContent=c.title;$('#proto-summary').textContent=c.summary;
 const count=state.events.filter(x=>x.caseId===caseId).length,available=Object.values(actions).filter(a=>a.role===role&&a.can(c)).length;
 $('#proto-stats').innerHTML='<article class="proto-card"><span>Vista activa</span><strong>'+esc(roles[role])+'</strong><small>Usuario ficticio · permisos de demo</small></article><article class="proto-card"><span>Decisiones disponibles</span><strong>'+available+'</strong><small>Para este rol y estado</small></article><article class="proto-card"><span>Eventos registrados</span><strong>'+count+'</strong><small>'+(storage?'Guardado en este navegador':'Solo memoria; almacenamiento no disponible')+'</small></article>';
 const limited=['banco','telco','osiptel'].includes(role);
 const evidence='<p>'+esc(limited?'Esta vista muestra identificadores sintéticos y alcance de la solicitud. El contenido de la amenaza se omite para la entidad ejecutora.':'Paquete sintético: mensaje de exigencia, constancia de procedencia y referencia de destino de cobro. No hay archivos, cuentas o personas reales.')+'</p><ul class="proto-evidence"><li>Integridad: '+(c.file==='draft'?'pendiente de preservación':'preservación ficticia registrada')+'</li><li>Corroboración: '+(c.sufficient?'suficiente en el escenario':'insuficiente; no puede remitirse')+'</li><li>Titularidad: no equivale a autoría; posibilidad de suplantación</li></ul>';
 const bankNext={draft:'Policía debe preservar y enviar.',pending_uif:'Pendiente de decisión UIF.',ordered:'Banco puede ejecutar; Juzgado puede revisar en paralelo.',frozen:'Inmovilización registrada; consultar control judicial.',incident:'UIF debe revisar incidencia antes del reenvío.',rejected:'Solicitud financiera rechazada; telecom conserva su propio estado.',cancelled:'Orden cancelada antes de ejecución; banco no puede inmovilizar.',release_pending:'Banco debe confirmar liberación.',released:'Liberación registrada.'};
 const telNext={draft:'Policía debe enviar el requerimiento.',pending_osiptel:'Pendiente de validación y traslado por OSIPTEL.',ordered:'Telco debe ejecutar o registrar incidencia.',blocked:'Baja registrada; Policía puede solicitar corrección.',incident:'Incidencia pendiente de OSIPTEL.',rejected:'Requerimiento devuelto; ruta financiera independiente.',restore_requested:'OSIPTEL debe validar la corrección.',restore_ordered:'Telco debe reactivar.',restored:'Reactivación registrada.'};
 $('#proto-workspace').innerHTML='<div class="proto-grid">'+card('Expediente y evidencia',c.file,evidence,['preserve','supplement','submit'],c)+card('Revisión fiscal de coordinación',c.fiscal,'<p>La Fiscalía registra su revisión del expediente y la coordinación investigativa. Este paso no se convierte en un permiso universal para otras entidades ni bloquea el control judicial de la medida financiera.</p>',['fiscal_review'],c)+'</div><div class="proto-grid">'+card('Ruta financiera · '+esc(c.account),c.bank,'<div class="proto-steps"><span class="proto-step">Policía → UIF → Banco</span><span class="proto-step">UIF → Juzgado → revisión</span></div><p><b>'+money(c.amount)+'</b> · monto ficticio de la medida. No se transfiere ni recupera dinero real.</p><p class="proto-notice">'+esc(bankNext[c.bank])+'</p>',['uif_approve','uif_reject','bank_execute','bank_incident','uif_retry','bank_release'],c)+card('Ruta telecom · '+esc(c.line),c.telco,'<div class="proto-steps"><span class="proto-step">Policía → OSIPTEL → Telco</span></div><p>Baja de línea ficticia. Este ejemplo no ordena borrar cuentas de mensajería ni demuestra que una amenaza haya cesado.</p><p class="proto-notice">'+esc(telNext[c.telco])+'</p>',['osiptel_approve','osiptel_reject','telco_execute','telco_incident','osiptel_retry','pnp_restore','osiptel_restore','telco_restore'],c)+'</div>'+card('Control judicial de la medida financiera',c.review,'<p>Disponible cuando UIF emite la medida. Puede convalidarse o revocarse sin esperar una aprobación fiscal de la demo. Si el banco ya inmovilizó, la revocación genera una liberación pendiente; si aún no ejecutó, cancela la orden.</p>',['judge_confirm','judge_revoke'],c);
 timeline();if(message)$('#proto-message').textContent=message;
}
$('#proto-role').addEventListener('change',ev=>{role=ev.target.value;render('Vista '+roles[role]+': '+help[role]);});
$('#proto-cases').addEventListener('click',ev=>{const target=ev.target.closest('[data-case]');if(target){caseId=target.dataset.case;render('Expediente '+caseId+' seleccionado.');}});
$('#proto-filter').addEventListener('change',timeline);
$('#proto-workspace').addEventListener('click',ev=>{const target=ev.target.closest('[data-action]');if(!target||target.disabled)return;pending={id:target.dataset.action,role,caseId};const a=actions[pending.id],c=state.cases.find(x=>x.id===caseId);$('#decision-title').textContent=a.label;$('#decision-context').textContent=caseId+' · '+roles[role]+' · '+snapshot(c);$('#decision-reason').innerHTML='<option value="">Selecciona un motivo</option><option value="'+esc(a.reason)+'">'+esc(a.reason)+'</option>';$('#proto-decision').showModal();});
$('#decision-cancel').addEventListener('click',()=>{$('#proto-decision').close();pending=null;});
$('#proto-decision').addEventListener('cancel',()=>{pending=null;});
$('#proto-decision-form').addEventListener('submit',ev=>{ev.preventDefault();if(!pending)return;const result=transition(state,{caseId:pending.caseId,role:pending.role,actionId:pending.id,reason:$('#decision-reason').value});state=result.state;save();$('#proto-decision').close();pending=null;render(result.ok?'Decisión registrada con rol, hora, motivo y estado antes/después. Ninguna acción real fue ejecutada.':result.error);});
$('#proto-reset').addEventListener('click',()=>{state=resetCase(state,caseId);save();render('Caso ficticio reiniciado. Se conserva la traza del recorrido anterior.');});
$('#proto-export').addEventListener('click',()=>{const c=state.cases.find(x=>x.id===caseId),payload={type:'educational_simulation',exported_at:new Date().toISOString(),timezone:'America/Lima',warning:'Datos ficticios. Historial local sin firma digital, autenticación institucional ni garantía contra alteraciones.',case:c,events:state.events.filter(x=>x.caseId===caseId)};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=caseId+'-traza-simulada.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#proto-message').textContent='Traza JSON del caso preparada para descargar. Contiene únicamente el ejercicio ficticio.';});
render();
